        },
        required: ['start_date', 'end_date'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'sales_report') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { start_date, end_date, ...rest } = args || {};
  if (Object.keys(rest).length > 0) {
    throw new Error('Unexpected fields: ' + Object.keys(rest).join(', '));
  }
  if (!isValidIsoDate(start_date)) {
    throw new Error('start_date must be a valid ISO date string (YYYY-MM-DD)');
  }
  if (!isValidIsoDate(end_date)) {
    throw new Error('end_date must be a valid ISO date string (YYYY-MM-DD)');
  }
  if (start_date > end_date) {
    throw new Error('start_date must not be after end_date');
  }
  let total = 0;
  let count = 0;
  for (const row of sales) {
    if (row.date >= start_date && row.date <= end_date) {
      total += row.amount;
      count += 1;
    }
  }
  const text = `Total amount: ${total}, Row count: ${count}`;
  return { content: [{ type: 'text', text }] };
}
